// Явное сопоставление полей лида с записью CRM/Google Sheets.
// Никаких «магических» переименований: все поля контракта перечислены здесь.
const lead = $json.body ?? $json;

const required = ['phone', 'full_name'];
const missing = required.filter((field) => !lead[field]);
if (missing.length > 0) {
  throw new Error(`crm_sync: отсутствуют обязательные поля: ${missing.join(', ')}`);
}

// $env.CRM_TARGET задаётся в настройках инстанса n8n (google_sheets | bitrix24 | amocrm).
const crmTarget = $env.CRM_TARGET || 'google_sheets';

return [{
  json: {
    external_id: `tg-${lead.telegram_id}-${lead.created_at}`,
    phone: lead.phone,
    full_name: lead.full_name,
    username: lead.username || '',
    comment: lead.comment || '',
    source: lead.source || 'telegram_bot',
    status: lead.status || 'new',
    created_at: lead.created_at,
    synced_at: new Date().toISOString(),
    crm_target: crmTarget,
  },
}];
